from search import first_nonnegative

def test_last_element_is_zero():
    assert first_nonnegative([-5, -2, 0]) == 2

def test_no_negative():
    assert first_nonnegative([1, 2]) == 0

def test_all_negative():
    assert first_nonnegative([-1, -2]) == 2

def test_empty():
    assert first_nonnegative([]) == 0


from parsing import parse_csv_line

def test_csv_quoted_comma():
    assert parse_csv_line('1,"x,y",3') == ["1", "x,y", "3"]

def test_csv_trailing_empty():
    assert parse_csv_line("a,b,") == ["a", "b", ""]

def test_csv_single():
    assert parse_csv_line("only") == ["only"]

def test_csv_quoted_semicolon():
    assert parse_csv_line('"a;b",c') == ["a;b", "c"]
